(()=>{const banner=`<section class="vsn-story-banner" aria-label="VSN Interiors leadership and studio introduction"><div class="vsn-banner-person vsn-banner-left"><img src="images/brand/founder-mahesh.webp" alt="Mahesh K, founder of VSN Interiors"></div><div class="vsn-banner-center"><p class="vsn-banner-overline">DESIGNED FOR LIFE · CRAFTED WITH CARE</p><span class="vsn-banner-line"></span><p class="vsn-banner-wordmark">VSN <em>INTERIORS</em></p><p class="vsn-banner-tag">Spaces that feel like you.</p><h1>The people behind<br><em>beautiful spaces.</em></h1><p class="vsn-banner-description">Thoughtful interiors, personal attention and a shared belief that every space deserves a story.</p><a class="vsn-banner-action" href="#/about#people">Meet our founders ↗</a></div><div class="vsn-banner-person vsn-banner-right"><img src="images/brand/founder-ravi.webp" alt="Ravi Kishore, co-founder of VSN Interiors"></div></section>`;
const highlights=`<section class="vsn-story-highlights studio-container" aria-label="Why choose VSN Interiors"><div class="vsn-story-highlights-heading"><span>OUR STUDIO AT A GLANCE</span><h2>Designed with purpose.<br><em>Made for real life.</em></h2></div><div class="vsn-story-highlights-grid"><article><span>01 / LISTEN</span><h3>Your vision comes first</h3><p>We understand the way you live, your practical needs and the mood you want to create before designing a single detail.</p></article><article><span>02 / VISUALISE</span><h3>See the possibilities</h3><p>Clear space planning, thoughtful materials and 3D visualisations help turn your ideas into an informed design direction.</p></article><article><span>03 / DELIVER</span><h3>Care in every detail</h3><p>From early concepts to execution and finishing touches, we work to make the process coordinated, transparent and personal.</p></article></div></section>`;
const founders=`<section id="people" class="vsn-founders studio-container"><div class="vsn-founders-heading"><p class="studio-kicker">MEET THE PEOPLE BEHIND VSN</p><h2>Two perspectives.<br><em>One shared vision.</em></h2><p>Our approach blends thoughtful design, practical execution and personal attention to every project.</p></div><div class="vsn-founders-grid"><article class="vsn-founder-profile"><div class="vsn-founder-portrait"><img src="images/brand/founder-mahesh.webp" alt="Mahesh K, founder of VSN Interiors" loading="lazy"></div><div class="vsn-founder-info"><span>FOUNDER · VSN INTERIORS</span><h3>Mahesh K</h3><p>Helping shape spaces around the people who use them, with a focus on design clarity, materials and thoughtful details.</p></div></article><article class="vsn-founder-profile"><div class="vsn-founder-portrait"><img src="images/brand/founder-ravi.webp" alt="Ravi Kishore, co-founder of VSN Interiors" loading="lazy"></div><div class="vsn-founder-info"><span>CO-FOUNDER · VSN INTERIORS</span><h3>Ravi Kishore</h3><p>Bringing a collaborative, hands-on perspective to interior projects, from understanding client priorities to bringing the design together.</p></div></article></div><a href="#/contact" class="vsn-founders-contact">Start a conversation with our team ↗</a></section>`;
const map=`<div class="vsn-map-frame"><div class="vsn-map-title">⌖ &nbsp; VISIT OUR STUDIO</div><iframe title="Map showing VSN Interiors studio, Dasannapeta, Vizianagaram" src="https://maps.google.com/maps?q=PJR%20Residency%2C%20Ayya%20Koneru%2C%20Dasannapeta%2C%20Vizianagaram%2C%20Andhra%20Pradesh%20535002&t=&z=15&ie=UTF8&iwloc=&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><a href="https://maps.app.goo.gl/wkB9M8cWYB8uzYCL8" target="_blank" rel="noopener noreferrer">Open directions in Google Maps ↗</a></div>`;
function apply(){const about=document.querySelector('.studio-about');if(about&&!about.querySelector('.vsn-story-banner')){const hero=about.querySelector(':scope > *');if(hero){hero.insertAdjacentHTML('beforebegin',banner+highlights+founders);hero.remove()}about.querySelector('.sa-people')?.remove();about.querySelector('.sa-cofounder')?.remove()}
const contact=document.querySelector('.vsn-contact');if(contact){const photo=contact.querySelector('.vsn-consult-photo');if(photo)photo.outerHTML=map;contact.querySelectorAll('.vsn-contact-direct > a').forEach(a=>a.classList.add('vsn-contact-dark'));}}
let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;apply()})}).observe(document.getElementById('app'),{childList:true,subtree:true});window.addEventListener('hashchange',()=>requestAnimationFrame(apply));apply();})();